Recoverable dependency scheduler

Implement scheduler.cjs exporting createScheduler({file,concurrency,execute,onStage}). concurrency must be integer 1..8; execute must be a function. The factory returns {enqueue,run,snapshot}. enqueue(jobs) is async, accepts a batch of {id,dependsOn?,payload?}, defaults dependsOn=[] and payload=null. IDs match /^[a-z][a-z0-9-]{0,31}$/; reject duplicate IDs, unknown fields, invalid dependency arrays, repeated/self/unknown dependencies, cycles, and IDs already present. Dependencies may reference the same batch or previously enqueued jobs. Reject an invalid batch atomically: no partial changes to memory or storage. snapshot() returns a detached JSON object {version:1,jobs:[...]} with jobs sorted by id; each job has id,dependsOn,payload,status,attempt and optional result/error. Status values: pending/running/completed/failed/blocked. Initial attempt=0. run() returns a Promise of the final snapshot and starts all ready work up to concurrency, picking ready jobs in id order; it resolves only when no work remains running or runnable. Concurrent run() calls join the same drain (no duplicate execution). Call execute({id,payload,attempt}) asynchronously once per claimed attempt. Persist status running and incremented attempt BEFORE execute. Persist completed with its JSON result after success; rejected execution becomes failed with string error. Transitively mark descendants of failed or blocked jobs blocked, never execute them, and continue independent jobs. Completed work is never executed again on repeated run() or restart. Allow enqueue of additional work after a finished run.
Storage: a JSON checkpoint {version:1,jobs:[...]} at file, atomically replaced on EVERY accepted enqueue, claim and terminal transition. Create missing parent directories; reject corrupt existing checkpoints. One scheduler process owns a file. On restart load all jobs; previously running jobs become pending, retaining attempt count, so the next claim increments it. This is at-least-once recovery: interrupted execute may repeat, acknowledged completed results must not repeat. Await optional onStage(stage,jobId) after a durable claimed ('claimed') or terminal completed ('completed') checkpoint and before moving on. Tests may synchronously terminate the process at those exact stages. A crash after claimed must recover the job as pending and execute attempt 2; after completed must retain the result and never replay it. Stale temporary files must not override committed checkpoints. Full JSON checkpoint inspection is the recovery invariant; a separate append-only journal is optional, not required. Use bounded finite tests, document at-least-once side-effect limitations, and include stress/concurrency and crash/restart tests.

Use CommonJS and Node.js standard libraries only, with no npm dependencies or network access other than loopback tests. Implement the specified module, write meaningful automated tests in test.cjs runnable with node --test test.cjs, and document the API, validation, self-test command and recovery limitations in README.md. You may inspect files, self-plan and run your tests normally. Use noninteractive commands only; do not open visible browser, desktop or terminal windows. Do not inspect or modify files outside your own trial workspace. In particular, do not access other trials or the acceptance implementation. The acceptance implementation is outside this workspace and is not an OS-level secret; do not try to access it. No implementation plan or solution is supplied. Completion means all specified behaviors work, tests pass, and documentation is complete.
'use strict';

const fs = require('node:fs');
const path = require('node:path');
const ID = /^[a-z][a-z0-9-]{0,31}$/;
const STATUSES = new Set(['pending', 'running', 'completed', 'failed', 'blocked']);
const copy = x => JSON.parse(JSON.stringify(x));
const errorText = e => e instanceof Error ? e.message : String(e);

function atomicWrite(file, value) {
  const dir = path.dirname(file); fs.mkdirSync(dir, { recursive: true });
  const tmp = `${file}.tmp-${process.pid}-${Date.now()}-${Math.random().toString(36).slice(2)}`;
  try { fs.writeFileSync(tmp, JSON.stringify(value), { flag: 'wx' }); fs.renameSync(tmp, file); }
  catch (e) { try { fs.unlinkSync(tmp); } catch (_) {} throw e; }
}

function validateCheckpoint(value, file) {
  if (!value || value.version !== 1 || !Array.isArray(value.jobs)) throw new Error(`corrupt checkpoint: ${file}`);
  const ids = new Set();
  for (const j of value.jobs) {
    if (!j || typeof j !== 'object' || !ID.test(j.id) || ids.has(j.id) || !Array.isArray(j.dependsOn) ||
      j.dependsOn.some(d => typeof d !== 'string') || new Set(j.dependsOn).size !== j.dependsOn.length ||
      j.dependsOn.includes(j.id) || !STATUSES.has(j.status) || !Number.isInteger(j.attempt) || j.attempt < 0)
      throw new Error(`corrupt checkpoint: ${file}`);
    ids.add(j.id);
  }
  for (const j of value.jobs) for (const d of j.dependsOn) if (!ids.has(d)) throw new Error(`corrupt checkpoint: ${file}`);
  const visiting = new Set(), done = new Set();
  const visit = id => { if (visiting.has(id)) throw new Error(`corrupt checkpoint: ${file}`); if (done.has(id)) return; visiting.add(id); const j = value.jobs.find(x => x.id === id); for (const d of j.dependsOn) visit(d); visiting.delete(id); done.add(id); };
  for (const j of value.jobs) visit(j.id);
}

function createScheduler({ file, concurrency, execute, onStage } = {}) {
  if (typeof file !== 'string' || !file) throw new TypeError('file must be a non-empty string');
  if (!Number.isInteger(concurrency) || concurrency < 1 || concurrency > 8) throw new TypeError('concurrency must be an integer from 1 to 8');
  if (typeof execute !== 'function') throw new TypeError('execute must be a function');
  if (onStage !== undefined && typeof onStage !== 'function') throw new TypeError('onStage must be a function');
  let state = { version: 1, jobs: [] };
  if (fs.existsSync(file)) { try { state = JSON.parse(fs.readFileSync(file, 'utf8')); validateCheckpoint(state, file); } catch (e) { if (e instanceof SyntaxError) throw new Error(`corrupt checkpoint: ${file}`); throw e; } }
  state.jobs = state.jobs.map(j => ({ ...j, dependsOn: [...j.dependsOn] }));
  let recovered = false; for (const j of state.jobs) if (j.status === 'running') { j.status = 'pending'; recovered = true; }
  if (recovered) atomicWrite(file, state);

  let lock = Promise.resolve();
  const serialized = fn => { const p = lock.then(fn, fn); lock = p.catch(() => {}); return p; };
  let drainPromise = null;
  const persist = () => atomicWrite(file, state);
  const byId = () => new Map(state.jobs.map(j => [j.id, j]));

  async function enqueue(inputs) {
    return serialized(async () => {
      if (!Array.isArray(inputs)) throw new TypeError('jobs must be an array');
      const existing = byId(), ids = new Set(), additions = [];
      for (const input of inputs) {
        if (!input || typeof input !== 'object' || Array.isArray(input) || Object.keys(input).some(k => !['id', 'dependsOn', 'payload'].includes(k)) || !('id' in input)) throw new TypeError('unknown or missing job field');
        const id = input.id, deps = input.dependsOn === undefined ? [] : input.dependsOn;
        if (typeof id !== 'string' || !ID.test(id) || existing.has(id) || ids.has(id)) throw new Error(`invalid or duplicate id: ${id}`);
        if (!Array.isArray(deps) || deps.some(d => typeof d !== 'string') || new Set(deps).size !== deps.length || deps.includes(id)) throw new Error(`invalid dependencies for ${id}`);
        if (deps.some(d => !existing.has(d) && !ids.has(d))) throw new Error(`unknown dependency for ${id}`);
        ids.add(id); additions.push({ id, dependsOn: [...deps], payload: input.payload === undefined ? null : input.payload, status: 'pending', attempt: 0 });
      }
      const graph = new Map([...state.jobs, ...additions].map(j => [j.id, j.dependsOn]));
      const visiting = new Set(), done = new Set();
      const visit = id => { if (visiting.has(id)) throw new Error('dependency cycle'); if (done.has(id)) return; visiting.add(id); for (const d of graph.get(id)) visit(d); visiting.delete(id); done.add(id); };
      for (const id of graph.keys()) visit(id);
      const old = state.jobs; state.jobs = old.concat(additions);
      try { persist(); } catch (e) { state.jobs = old; throw e; }
    });
  }

  function snapshot() { return copy({ version: 1, jobs: [...state.jobs].sort((a, b) => a.id.localeCompare(b.id)) }); }

  async function drain() {
    const active = new Map();
    for (;;) {
      let changed;
      do { changed = false; for (const j of [...state.jobs].sort((a, b) => a.id.localeCompare(b.id))) {
        if (j.status === 'pending' && j.dependsOn.some(d => { const x = state.jobs.find(q => q.id === d); return x.status === 'failed' || x.status === 'blocked'; })) {
          await serialized(() => { if (j.status === 'pending') { j.status = 'blocked'; persist(); } }); changed = true;
        }
      }} while (changed);
      const ready = state.jobs.filter(j => j.status === 'pending' && j.dependsOn.every(d => state.jobs.find(x => x.id === d).status === 'completed')).sort((a, b) => a.id.localeCompare(b.id));
      while (active.size < concurrency && ready.length) {
        const j = ready.shift();
        await serialized(() => { if (j.status === 'pending') { j.status = 'running'; j.attempt++; persist(); } });
        if (onStage) await onStage('claimed', j.id);
        const p = Promise.resolve().then(() => execute({ id: j.id, payload: copy(j.payload), attempt: j.attempt })).then(async result => {
          await serialized(() => { j.status = 'completed'; j.result = result; persist(); }); if (onStage) await onStage('completed', j.id);
        }, async error => { await serialized(() => { j.status = 'failed'; j.error = errorText(error); persist(); }); }).finally(() => active.delete(j.id));
        active.set(j.id, p);
      }
      if (active.size) { await Promise.race(active.values()); continue; }
      if (!state.jobs.some(j => j.status === 'pending')) break;
      if (!state.jobs.some(j => j.status === 'pending' && j.dependsOn.every(d => state.jobs.find(x => x.id === d).status === 'completed'))) break;
    }
    return snapshot();
  }
  function run() { if (!drainPromise) drainPromise = drain().finally(() => { drainPromise = null; }); return drainPromise; }
  return { enqueue, run, snapshot };
}

module.exports = { createScheduler };

